// Close is to release resource of ConnPool, it is executed when client is closed.
func (p *connPool) Close() error {
	p.conns.Range(func(addr, trans interface{}) bool {
		p.conns.Delete(addr)
		trans.(*transports).close()
		return true
	})
	return nil
}

// Dump returns a diagnostic string describing the current state of the connection pool
// including active connections, addresses, and transport states.
func (p *connPool) Dump() string {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("ConnPool[service=%s, size=%d]:\n", p.remoteService, p.size))

	connCount := 0
	p.conns.Range(func(addr, trans interface{}) bool {
		connCount++
		address := addr.(string)
		transports := trans.(*transports)

		sb.WriteString(fmt.Sprintf("  [%d] Address: %s\n", connCount, address))

		activeCount := 0
		inactiveCount := 0
		nilCount := 0

		for i := 0; i < int(transports.size); i++ {
			tr := transports.cliTransports[i]
			if tr == nil {
				nilCount++
				continue
			}
			if tr.(grpc.IsActive).IsActive() {
				activeCount++
			} else {
				inactiveCount++
			}
		}

		sb.WriteString(fmt.Sprintf("      Active: %d, Inactive: %d, Nil: %d\n", 
			activeCount, inactiveCount, nilCount))

		return true
	})

	if connCount == 0 {
		sb.WriteString("  (no connections)\n")
	}

	return sb.String()
}

